update data_auth_mapper_config set filter_sql='select tt.* from (select b.*,nvl(di.belongInstitutionCode,COD.ORG_CODE) belongInstitutionCode,di.model_type from ( %s ) b LEFT JOIN (select di.business_id  finprod_market_id,di.institution_code,di.belong_institution_code belongInstitutionCode,di.model_type from  DATA_AUTH_NOTIFY_INST di where di.model_type = ''02'' and DI.DATA_TYPE=''PTL01'') di on di.finprod_market_id = b.PRODID left join  CHB_ORG_REGIST_BANK_CODE COD ON b.issuePartyId=COD.REGIST_BANK_CODE)tt where tt.belongInstitutionCode in %s'
where sql_id='com.joyintech.tams.svreport.chb.perprodeclarereg.dao.PerProDeclareReg001Mapper.selectAllData';